#include <bits/stdc++.h>
using namespace std;

long long power(long long base, int exp, int mod) {
    long long res = 1;
    long long b = base % mod;
    for (int i = 0; i < 64; i++) {
        if (((exp >> i) & 1) == 1) res = res * b % mod;
        b = b * b % mod;
    }
    return res;
}

long long combination(int n, int r, int mod, vector<vector<long long>>& factorials) {
    if (n < 0 || r < 0 || r > n) return 0;
    return factorials[0][n] * factorials[1][r] % mod * factorials[1][n - r] % mod;
}

vector<vector<long long>> computeFactorials(int n, int mod) {
    vector<long long> fact(n + 1);
    vector<long long> invFact(n + 1);
    fact[0] = 1;
    for (int i = 1; i <= n; i++) {
        fact[i] = fact[i - 1] * i % mod;
    }
    long long invNFact = power(fact[n], mod - 2, mod);
    invFact[n] = invNFact;
    for (int i = n - 1; i >= 0; i--) {
        invFact[i] = invFact[i + 1] * (i + 1) % mod;
    }
    return {fact, invFact};
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int mod = 998244353;
    int n;
    long long K;
    cin >> n >> K;
    if (K >= n) {
        cout << 0 << "\n";
        return 0;
    }
    auto factorials = computeFactorials(n, mod);
    if (K == 0) {
        cout << factorials[0][n] << "\n";
        return 0;
    }
    long long resultSum = 0;
    for (int i = n - (int)K; i >= 1; i--) {
        int sign = (((n - (int)K) - i) % 2 == 0) ? 1 : -1;
        long long comb = combination(n, i, mod, factorials);
        long long powerVal = power(i, n, mod);
        long long term = comb * powerVal % mod;
        if (sign == -1) term = (mod - term) % mod;
        long long comb2 = combination(n - i, (int)K, mod, factorials);
        resultSum = (resultSum + term * comb2) % mod;
    }
    resultSum = (resultSum * 2) % mod;
    cout << resultSum << "\n";
    return 0;
}

